const rawOutput = $json.output ?? $json.text ?? $json.response ?? $json;

function parseJsonSafely(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return value;
  }

  let text = String(value || '').trim();

  // Remove possible markdown code fences
  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch (error) {
    const firstBrace = text.indexOf('{');
    const lastBrace = text.lastIndexOf('}');

    if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
      try {
        return JSON.parse(text.slice(firstBrace, lastBrace + 1));
      } catch (innerError) {
        return null;
      }
    }

    return null;
  }
}

function toBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;

  if (typeof value === 'string') {
    return value.trim().toLowerCase() === 'true';
  }

  return Boolean(value);
}

const parsed = parseJsonSafely(rawOutput);

const isReplyToOriginalPaulaEmail = toBoolean(
  $('Extract Applicant Reply').first().json.isReplyToOriginalPaulaEmail
);

const applicantReplyText = String(
  $('Extract Applicant Reply').first().json.applicantReplyText || ''
).trim();

if (!parsed) {
  return [
    {
      json: {
        isReplyToOriginalPaulaEmail,
        applicantReplyText,
        candidateIntent: 'unclear',
        shouldSendNextStage: false,
        shouldSendNotInterested: false,
        shouldFlagManualReview: true,
        confidence: 0,
        reason: 'AI returned invalid JSON',
        matchedSignals: [],
        route: 'manual_review',
      },
    },
  ];
}

const allowedIntents = [
  'move_forward',
  'not_interested',
  'question',
  'unclear',
  'other',
];

const candidateIntent = allowedIntents.includes(parsed.candidateIntent)
  ? parsed.candidateIntent
  : 'unclear';

const shouldSendNextStage = toBoolean(parsed.shouldSendNextStage);
const shouldSendNotInterested = toBoolean(parsed.shouldSendNotInterested);
const shouldFlagManualReview = toBoolean(parsed.shouldFlagManualReview);
const confidence = Number(parsed.confidence ?? 0);

let route = 'manual_review';

if (
  isReplyToOriginalPaulaEmail &&
  candidateIntent === 'move_forward' &&
  shouldSendNextStage &&
  confidence >= 0.9
) {
  route = 'next_stage';
}

if (
  isReplyToOriginalPaulaEmail &&
  candidateIntent === 'not_interested' &&
  shouldSendNotInterested &&
  confidence >= 0.85
) {
  route = 'not_interested';
}

// Safety rule:
// Questions, unclear replies, and other replies must never go to not_interested.
if (['question', 'unclear', 'other'].includes(candidateIntent)) {
  route = 'manual_review';
}

return [
  {
    json: {
      isReplyToOriginalPaulaEmail,
      applicantReplyText,

      candidateIntent,
      shouldSendNextStage,
      shouldSendNotInterested,
      shouldFlagManualReview,

      confidence,
      reason: String(parsed.reason ?? ''),
      matchedSignals: Array.isArray(parsed.matchedSignals)
        ? parsed.matchedSignals.map(signal => String(signal))
        : [],

      route,
    },
  },
];

const triggerMessageId = $('Flo Labs HR Gmail Trigger').first().json.id;
const messages = $json.messages || [];

const AUTO_REPLY_MARKER = 'FLOLABS_NEXT_STAGE_REPLY_V1';

function hasSentLabel(message) {
  const rawLabelIds = Array.isArray(message.labelIds) ? message.labelIds : [];
  const rawLabels = Array.isArray(message.labels) ? message.labels : [];

  const normalized = [
    ...rawLabelIds,
    ...rawLabels.map(label => {
      if (typeof label === 'string') return label;
      return label?.id || label?.name || '';
    }),
  ].map(value => String(value).toUpperCase());

  return normalized.includes('SENT');
}

function decodeBase64Url(value) {
  if (!value || typeof value !== 'string') return '';

  try {
    const normalized = value.replace(/-/g, '+').replace(/_/g, '/');
    return Buffer.from(normalized, 'base64').toString('utf8');
  } catch (error) {
    return '';
  }
}

function collectPayloadText(payload) {
  if (!payload) return '';

  let output = '';

  if (payload.body?.data) {
    output += '\n' + decodeBase64Url(payload.body.data);
  }

  if (Array.isArray(payload.parts)) {
    for (const part of payload.parts) {
      output += '\n' + collectPayloadText(part);
    }
  }

  return output;
}

function messageText(message) {
  return [
    message?.text || '',
    message?.textPlain || '',
    message?.html || '',
    message?.body || '',
    message?.snippet || '',
    collectPayloadText(message?.payload),
    JSON.stringify(message || ''),
  ].join('\n');
}

const currentMessage = messages.find(message => message.id === triggerMessageId);

if (!currentMessage) {
  return [
    {
      json: {
        ...$json,
        alreadyReplied: false,
        matchedReplyMessageId: null,
        matchedReplyDate: null,
        note: 'Current incoming message was not found inside the fetched thread.',
      },
    },
  ];
}

const currentInternalDate = Number(currentMessage.internalDate || 0);

const previousAutoReply = messages
  .filter(message => message.id !== triggerMessageId)
  .filter(message => Number(message.internalDate || 0) < currentInternalDate)
  .filter(message => hasSentLabel(message))
  .find(message => messageText(message).includes(AUTO_REPLY_MARKER));

return [
  {
    json: {
      ...$json,
      alreadyReplied: Boolean(previousAutoReply),
      matchedReplyMessageId: previousAutoReply?.id || null,
      matchedReplyDate: previousAutoReply?.internalDate || null,
    },
  },
];

const candidateEmail = String(
  $('(Got First Email) Email Parameters').first().json.from?.value?.[0]?.address ||
  ''
).trim().toLowerCase();

const items = $input.all();

const realMatches = items.filter(item => {
  return item.json && item.json.id;
});

const nextStageEmailAlreadySent = realMatches.length > 0;

return [
  {
    json: {
      candidateEmail,
      nextStageEmailAlreadySent,
      matchedMessageId: realMatches[0]?.json?.id || null,
      matchedThreadId: realMatches[0]?.json?.threadId || null,
      checkedBy: 'gmail_sent_search',
      searchQuery: 'in:sent to:' + candidateEmail + ' "flolabsrd.fillout.com/t/besSHDQpaHus"',
      matchedCount: realMatches.length,
    },
  },
];

// === Extract ONLY the applicant's new reply text ===
const triggerMessageId = $('Flo Labs HR Gmail Trigger').first().json.id;
const messages = $json.messages || [];

function decodeBase64Url(value) {
  if (!value || typeof value !== 'string') return '';
  try {
    const normalized = value.replace(/-/g, '+').replace(/_/g, '/');
    return Buffer.from(normalized, 'base64').toString('utf8');
  } catch (error) {
    return '';
  }
}

function extractBodies(payload, acc) {
  if (!payload) return acc;
  const mime = (payload.mimeType || '').toLowerCase();
  if (payload.body?.data) {
    const decoded = decodeBase64Url(payload.body.data);
    if (mime === 'text/plain') acc.plain += '\n' + decoded;
    else if (mime === 'text/html') acc.html += '\n' + decoded;
  }
  if (Array.isArray(payload.parts)) {
    for (const part of payload.parts) extractBodies(part, acc);
  }
  return acc;
}

function htmlToText(html) {
  return html
    .replace(/<blockquote[\s\S]*?<\/blockquote>/gi, '') // drop the quoted original
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&')
    .replace(/&#39;/g, "'").replace(/&quot;/gi, '"')
    .trim();
}

function stripQuotedHistory(text) {
  if (!text) return '';
  const out = [];
  for (const line of text.split(/\r?\n/)) {
    if (/^\s*On .+wrote:\s*$/.test(line)) break;             // Gmail attribution line
    if (/^\s*-+\s*Original Message\s*-+/i.test(line)) break; // Outlook style
    if (/^\s*>/.test(line)) continue;                         // quoted lines
    out.push(line);
  }
  return out.join('\n').trim();
}

const currentMessage = messages.find(m => m.id === triggerMessageId);

let applicantReplyText = '';
let isReplyToThread = false;

if (currentMessage) {
  // deterministic reply check: headers + thread membership
  const headers = currentMessage.payload?.headers || [];
  const headerMap = {};
  for (const h of headers) headerMap[(h.name || '').toLowerCase()] = h.value || '';
  isReplyToThread = Boolean(
    headerMap['in-reply-to'] || headerMap['references'] || currentMessage.threadId
  );

  const bodies = extractBodies(currentMessage.payload, { plain: '', html: '' });
  let raw = bodies.plain.trim();
  if (!raw && bodies.html.trim()) raw = htmlToText(bodies.html);
  applicantReplyText = stripQuotedHistory(raw);
  if (!applicantReplyText) {
    applicantReplyText = (currentMessage.snippet || '').split(/On .+wrote:/)[0].trim();
  }
}

return [
  {
    json: {
      ...$json,
      applicantReplyText,
      isReplyToOriginalPaulaEmail: isReplyToThread,
    },
  },
];

